import React, { useState } from 'react';

export default function Login({ setShowLoginModal, handleLoginSubmit }) {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const onSubmit = (e) => {
        e.preventDefault();
        handleLoginSubmit(username, password);
    };

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
            
            <div style={{ display: 'flex', width: '800px', height: '450px', background: 'white', borderRadius: '20px', overflow: 'hidden', boxShadow: '0 10px 30px rgba(0,0,0,0.3)' }}>
                
                {/* වම් පැත්ත: Banner */}
                <div style={{ width: '50%', backgroundColor: '#1b5e20', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '20px', textAlign: 'center', color: 'white' }}>
                    <h2 style={{ lineHeight: '1.5' }}>Aura Pan Saku<br/>Educational<br/>Institute</h2>
                </div>
                
                {/* දකුණු පැත්ත: Form */}
                <div style={{ width: '50%', padding: '40px', display: 'flex', flexDirection: 'column', justifyContent: 'center', position: 'relative' }}>
                    <button onClick={() => setShowLoginModal(false)} style={{ position: 'absolute', top: '20px', right: '20px', background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer', color: '#999' }}>✖</button>

                    <h2 style={{ marginBottom: '30px', color: '#1b5e20', fontSize: '28px', fontWeight: 'bold' }}>Welcome Back!</h2>
                    
                    <form onSubmit={onSubmit} style={{ display: 'flex', flexDirection: 'column' }}>
                        
                        <label style={{ marginBottom: '8px', color: '#000', fontSize: '14px', fontWeight: 'bold' }}>User Name</label>
                        <input type="text" placeholder="Enter your user name" onChange={(e) => setUsername(e.target.value)} required style={{ padding: '12px', marginBottom: '20px', border: '1px solid #81c784', borderRadius: '25px', background: '#f1f8e9', outline: 'none' }} />
                        
                        <label style={{ marginBottom: '8px', color: '#000', fontSize: '14px', fontWeight: 'bold' }}>Password</label>
                        <input type="password" placeholder="Enter your password" onChange={(e) => setPassword(e.target.value)} required style={{ padding: '12px', marginBottom: '15px', border: '1px solid #81c784', borderRadius: '25px', background: '#f1f8e9', outline: 'none' }} />
                        
                        <p style={{ fontSize: '11px', color: '#555', textAlign: 'center', marginBottom: '20px', lineHeight: '1.4' }}>
                            If you have forgotten your username or password,<br/>please contact the class to retrieve it.
                        </p>
                        
                        <button type="submit" style={{ padding: '12px', background: '#2e7d32', color: 'white', border: 'none', borderRadius: '25px', cursor: 'pointer', fontWeight: 'bold', fontSize: '16px' }}>
                            Login
                        </button>
                    </form>
                </div>

            </div>
        </div>
    );
}
